6. void light_control(void) {
7. u8 j;
8. u16 light_value;
9. static u32 systick_ms_light = 0;
10. //每隔 500 毫秒执行一次
11. if(millis() - systick_ms_light >= 500){
12. systick_ms_light = millis();
13. light_value = ADC_ConvertedValue[0]; //获取光敏传感器的 AD 值
14. //sprintf((char *)cmd_return,"light_value:%d\r\n",(int)light_valu
e);
15. //uart1_send_str(cmd_return);
16. //无光照时，光敏值最大 1024，计算得出机械臂弯曲时的舵机 pwm 值
17. servo_pwm[1] = 1150 + light_value/4;
18. servo_pwm[2] = 1250 + light_value/4;
19. servo_pwm[3] = 1950 - light_value/4;
20. //光照强时机械臂直立
21. if(servo_pwm[1] < 1500){servo_pwm[1] = 1500;}
22. if(servo_pwm[2] < 1500){servo_pwm[2] = 1500;}
23. if(servo_pwm[3] > 1500){servo_pwm[3] = 1500;}
24. //控制 1，2，3 号舵机使机械臂弯曲
25. for(j=1;j<4;j++) {
26. set_servo(j, servo_pwm[j], 1000);
27. }
28. }
29. }
六、程序逻辑
检测光敏传感器的模拟值换算为舵机转动的PWM值，从而控制机械臂弯曲-直立。

